import { ImageIntakeStore } from "./image-intake.js"
import { mountImageRoutes } from "./image-web.js"
import { readFileSync } from "node:fs"
import { ReportFiles } from "./report-files.js"
import { fileURLToPath } from "node:url"

import { parseSkillFile } from "./skill-file.js"
import { mountPrevisitWebRoutes, type WebServer } from "./previsit-web.js"
import { registerPrevisitTools, type ToolHost } from "./previsit-tools.js"
import { PrevisitWorkflowStore, type StorageDomain } from "./previsit-workflow.js"

export const inject = ["skills", "tools"] as const

export const SKILL_NAME = "qcc-previsit-onepager"
export const SKILL_DESCRIPTION =
  "调用企查查五类 MCP 执行企业访前尽调，以机会与风险双引擎识别经营状态、建立并反证业务假设，交付可追溯的访前尽调报告。"

type SkillRegistration = {
  name: string
  description: string
  whenToUse: string
  content: string
  source: "bundled"
  resourceBase: {
    kind: "directory"
    path: string
  }
  metadata: Readonly<Record<string, unknown>>
}

export type HostContext = ToolHost & {
  effect(setup: () => void | (() => void)): unknown
  inject?(deps: string[], setup: (ctx: HostContext & { webServer: WebServer; storageDomain: StorageDomain }) => void): unknown
  logger?: { info?(message: string): void; warn?(message: string): void }
  skills: {
    register(skill: SkillRegistration): () => void
  }
}

export function loadBundledSkill(): SkillRegistration {
  const skillDirectoryUrl = new URL("../skills/qcc-previsit-onepager/", import.meta.url)
  const skillSource = readFileSync(new URL("SKILL.md", skillDirectoryUrl), "utf8")
  const { content } = parseSkillFile(skillSource)

  return {
    name: SKILL_NAME,
    description: SKILL_DESCRIPTION,
    whenToUse: "用户要求准备客户拜访、访前尽调、一页纸简报、授信面谈、商务谈判、签约核查、复访更新、触达路径或当面提问清单时使用。",
    content,
    source: "bundled",
    resourceBase: {
      kind: "directory",
      path: fileURLToPath(skillDirectoryUrl),
    },
    metadata: {
      author: "QCC",
      version: "0.1.32",
      industry: "enterprise-services",
      mcpServers: ["qcc-company", "qcc-risk", "qcc-ipr", "qcc-operation", "qcc-executive"],
    },
  }
}

export function apply(ctx: HostContext): void {
  const workflow = new PrevisitWorkflowStore()
  const files = new ReportFiles()
  const images = new ImageIntakeStore(ctx.tools)
  ctx.effect(() => registerPrevisitTools(ctx, workflow, { images, files }))
  ctx.effect(() => () => { void images.dispose() })
  ctx.skills.register(loadBundledSkill())
  ctx.inject?.(["webServer"], webCtx => {
    webCtx.effect(() => mountImageRoutes(webCtx.webServer, images))
  })
  try {
    ctx.inject?.(["webServer", "storageDomain"], webCtx => {
      void workflow.attach(webCtx.storageDomain, ctx.logger)
      void files.attach(webCtx.storageDomain).catch(error => ctx.logger?.warn?.(`报告文件存储未就绪：${String(error)}`))
      webCtx.effect(() => mountPrevisitWebRoutes(webCtx.webServer, workflow, files))
    })
  } catch (error) {
    ctx.logger?.warn?.(`[dsh-pre-duediligence] Host task routes unavailable: ${error instanceof Error ? error.message : String(error)}`)
  }
}
